            public override Nodes.JsonObject TransformSomething(
                Our.ISomething that
            )
            {
                var result = new Nodes.JsonObject();

                SetProperty(
                    result,
                    "structuralProperty",
                    "StructuralProperty",
                    that.StructuralProperty,
                    Serialize_IUnion);

                SetProperty(
                    result,
                    "mixedProperty",
                    "MixedProperty",
                    that.MixedProperty,
                    Serialize_IUnion);

                SetProperty(
                    result,
                    "modelTypedProperty",
                    "ModelTypedProperty",
                    that.ModelTypedProperty,
                    Serialize_IUnion);

                SetProperty(
                    result,
                    "listStructuralProperty",
                    "ListStructuralProperty",
                    that.ListStructuralProperty,
                    Serialize_ListOf_StructuralUnion);

                SetProperty(
                    result,
                    "listMixedProperty",
                    "ListMixedProperty",
                    that.ListMixedProperty,
                    Serialize_ListOf_MixedUnion);

                SetProperty(
                    result,
                    "listModelTypedProperty",
                    "ListModelTypedProperty",
                    that.ListModelTypedProperty,
                    Serialize_ListOf_ModelTypedUnion);

                SetProperty(
                    result,
                    "tupleProperty",
                    "TupleProperty",
                    that.TupleProperty,
                    Serialize_TupleOf3_StructuralUnion_MixedUnion_ModelTypedUnion);

                if (that.OptionalStructuralProperty != null)
                {
                    SetProperty(
                        result,
                        "optionalStructuralProperty",
                        "OptionalStructuralProperty",
                        that.OptionalStructuralProperty,
                        Serialize_IUnion);
                }

                if (that.OptionalMixedProperty != null)
                {
                    SetProperty(
                        result,
                        "optionalMixedProperty",
                        "OptionalMixedProperty",
                        that.OptionalMixedProperty,
                        Serialize_IUnion);
                }

                if (that.OptionalModelTypedProperty != null)
                {
                    SetProperty(
                        result,
                        "optionalModelTypedProperty",
                        "OptionalModelTypedProperty",
                        that.OptionalModelTypedProperty,
                        Serialize_IUnion);
                }

                if (that.OptionalListOverlappingProperty != null)
                {
                    SetProperty(
                        result,
                        "optionalListOverlappingProperty",
                        "OptionalListOverlappingProperty",
                        that.OptionalListOverlappingProperty,
                        Serialize_ListOf_OverlappingUnion);
                }

                return result;
            }
        }  // internal class Transformer

        /// <summary>
        /// Serialize instances of meta-model classes to JSON elements.
        /// </summary>
        /// <example>
        /// Here is an example how to serialize an instance of StructuralFirst:
        /// <code>
        /// var anInstance = new Our.StructuralFirst(
        ///     // ... some constructor arguments ...
        /// );
        /// System.Text.Json.Nodes.JsonObject element = (
        ///     Serialize.ToJsonObject(
        ///         anInstance));
        /// </code>
        /// </example>
        public static class Serialize
        {
            /// <summary>
            /// Serialize an instance of the meta-model into a JSON object.
            /// </summary>
            /// <exception cref="SerializationException">
            /// Thrown when a value within <paramref name="that" /> instance can not be
            /// represented in JSON
            /// </exception>
            public static Nodes.JsonObject ToJsonObject(Our.IClass that)
            {
                try
                {
                    return Transformer.TransformIClass(that);
                }
                catch (SerializationFailure failure)
                {
                    throw new SerializationException(
                        Reporting.GenerateCSharpPath(failure.Error.PathSegments),
                        failure.Error.Cause);
